#include "kernel/stat.h"
#include "user/user.h"

static void
priority_child(int gate_read, int gate_write)
{
  char token;
  int pid;
  int value;
  uint start;
  volatile uint work = 0;

  close(gate_write);
  if (read(gate_read, &token, 1) != 1) {
    printf("priority child: gate read failed\n");
    exit(1);
  }
  close(gate_read);

  pid = getpid();
  value = nice(pid, 0);
  printf("priority child start pid=%d nice=%d\n", pid, value);
  start = uptime();
  while (uptime() - start < 4)
    work++;
  printf("priority child finished pid=%d nice=%d\n", pid, value);
  exit(0);
}

static void
priority_test(void)
{
  int gate[2];
  int plus10;
  int plus5;
  char tokens[2] = {'a', 'b'};

  if (nice(getpid(), -20) != -20) {
    printf("priority test: failed to set parent nice value\n");
    exit(1);
  }
  if (pipe(gate) < 0) {
    printf("priority test: pipe failed\n");
    exit(1);
  }

  plus10 = fork();
  if (plus10 < 0) {
    printf("priority test: first fork failed\n");
    exit(1);
  }
  if (plus10 == 0)
    priority_child(gate[0], gate[1]);
  if (nice(plus10, 10) != 10) {
    printf("priority test: failed to set +10 child\n");
    exit(1);
  }

  plus5 = fork();
  if (plus5 < 0) {
    printf("priority test: second fork failed\n");
    exit(1);
  }
  if (plus5 == 0)
    priority_child(gate[0], gate[1]);
  if (nice(plus5, 5) != 5) {
    printf("priority test: failed to set +5 child\n");
    exit(1);
  }

  close(gate[0]);
  printf("priority test: both children created and assigned; releasing gate\n");
  if (write(gate[1], tokens, sizeof(tokens)) != sizeof(tokens)) {
    printf("priority test: gate write failed\n");
    exit(1);
  }
  close(gate[1]);

  wait(0);
  wait(0);
  printf("priority test complete; predicted work order: nice 5, then nice 10\n");
  exit(0);
}

int
main(int argc, char *argv[])
{
  int fd;
  char enabled_data[] = "logged while enabled\n";
  char disabled_data[] = "logged while disabled\n";

  if (argc > 1 && strcmp(argv[1], "priority") == 0)
    priority_test();

  startlogging();
  printf("startlogging returned\n");

  fd = open("log-enabled", O_CREATE | O_TRUNC | O_WRONLY);
  if (fd < 0 || write(fd, enabled_data, sizeof(enabled_data) - 1) < 0) {
    printf("logtest: enabled write failed\n");
    exit(1);
  }
  close(fd);

  stopLogging();
  printf("stopLogging returned\n");

  fd = open("log-disabled", O_CREATE | O_TRUNC | O_WRONLY);
  if (fd < 0 || write(fd, disabled_data, sizeof(disabled_data) - 1) < 0) {
    printf("logtest: disabled write failed\n");
    exit(1);
  }
  close(fd);

  printf("logtest complete\n");
  exit(0);







}

